","import React from "react";
import { RegionT } from "../../data/command";

const FLAG: Record<string, string> = { green: "#12a06d", amber: "#d9820a", red: "#e5484d", cyan: "#0a99c7" };
export type MapLayer = "density" | "participation" | "highpotential" | "assessments" | "velocity";

// Real OpenStreetMap slippy map — raster tiles rendered as <img> (no npm dependency,
// no external scripts). Web-Mercator projection, pan + zoom, clickable region markers
// and layer overlays. Degrades to the base canvas if tile images are CSP-blocked.
const TILE = 256;
const lon2x = (lon: number, z: number) => ((lon + 180) / 360) * TILE * 2 ** z;
const lat2y = (lat: number, z: number) => {
 const s = Math.sin((lat * Math.PI) / 180);
 return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * TILE * 2 ** z;
};

export function TalentMapLeaflet({ regions, layer, selected, onSelect }:
 { regions: RegionT[]; layer: MapLayer; selected: string | null; onSelect: (k: string) => void }) {
 const boxRef = React.useRef<HTMLDivElement | null>(null);
 const [size, setSize] = React.useState({ w: 620, h: 320 });
 const [cam, setCam] = React.useState(() => ({ z: 5, cx: lon2x(45.0, 5), cy: lat2y(24.0, 5) }));
 const [tip, setTip] = React.useState<{ x: number; y: number; r: RegionT } | null>(null);
 const drag = React.useRef<{ x: number; y: number; cx: number; cy: number; moved: boolean } | null>(null);

 React.useEffect(() => {
 const el = boxRef.current; if (!el) return;
 const measure = () => setSize({ w: el.clientWidth || 620, h: el.clientHeight || 320 });
 measure();
 const RO = (window as any).ResizeObserver;
 if (!RO) return;
 const ro = new RO(measure); ro.observe(el);
 return () => ro.disconnect();
 }, []);

 const n = 2 ** cam.z;
 const originX = cam.cx - size.w / 2, originY = cam.cy - size.h / 2;

 // build tile grid covering the viewport
 const tiles: { key: string; url: string; left: number; top: number }[] = [];
 const x0 = Math.floor(originX / TILE), x1 = Math.floor((originX + size.w) / TILE);
 const y0 = Math.floor(originY / TILE), y1 = Math.floor((originY + size.h) / TILE);
 for (let tx = x0; tx <= x1; tx++)
 for (let ty = y0; ty <= y1; ty++) {
 if (ty < 0 || ty >= n) continue;
 const wx = ((tx % n) + n) % n;
 tiles.push({ key: `${tx}_${ty}`, url: `https://tile.openstreetmap.org/${cam.z}/${wx}/${ty}.png`, left: tx * TILE - originX, top: ty * TILE - originY });
 }

 const project = (r: RegionT) => ({ x: lon2x(r.lng, cam.z) - originX, y: lat2y(r.lat, cam.z) - originY });
 const metric = (r: RegionT) =>
 layer === "density" ? r.discovered : layer === "participation" ? r.assessed :
 layer === "highpotential" ? r.highPotential : layer === "velocity" ? r.velocity : r.pathways;
 const max = Math.max(...regions.map(metric));
 const cluster = layer === "highpotential" || layer === "assessments";
 const layerWord = layer === "density" ? "discovered" : layer === "participation" ? "assessed" : layer === "highpotential" ? "high-potential" : layer === "velocity" ? "dev velocity" : "pathways";

 const zoomTo = (dz: number) => setCam(c => {
 const z = Math.min(9, Math.max(4, c.z + dz)); if (z === c.z) return c;
 const f = 2 ** (z - c.z); return { z, cx: c.cx * f, cy: c.cy * f };
 });
 const onWheel = (e: React.WheelEvent) => { e.preventDefault(); zoomTo(e.deltaY < 0 ? 1 : -1); };
 const onDown = (e: React.PointerEvent) => { drag.current = { x: e.clientX, y: e.clientY, cx: cam.cx, cy: cam.cy, moved: false }; };
 const onMove = (e: React.PointerEvent) => {
 const d = drag.current; if (!d) return;
 const dx = e.clientX - d.x, dy = e.clientY - d.y;
 if (Math.abs(dx) + Math.abs(dy) > 4) d.moved = true;
 setCam(c => ({ ...c, cx: d.cx - dx, cy: d.cy - dy }));
 };
 const onUp = () => { drag.current = null; };
 const clicked = (k: string) => { if (!drag.current?.moved) onSelect(k); };

 return (
 <div className="cc-mapbox" ref={boxRef} onWheel={onWheel} onPointerDown={onDown} onPointerMove={onMove}
 onPointerUp={onUp} onPointerLeave={() => { onUp(); setTip(null); }}
 style={{ cursor: drag.current ? "grabbing" : "grab", touchAction: "none" }}>
 {/* raster tile layer */}
 <div style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
 {tiles.map(t => (
 <img key={t.key} src={t.url} alt="" draggable={false}
 onError={e => { (e.currentTarget as HTMLImageElement).style.visibility = "hidden"; }}
 style={{ position: "absolute", left: t.left, top: t.top, width: TILE, height: TILE, userSelect: "none" }} />
 ))}
 </div>

 {/* marker overlay */}
 <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none" }}>
 {regions.map(r => {
 const p = project(r); if (p.x < -40 || p.y < -40 || p.x > size.w + 40 || p.y > size.h + 40) return null;
 const c = FLAG[r.flag], sel = selected === r.key, t = metric(r) / max;
 return (
 <g key={r.key} style={{ cursor: "pointer", pointerEvents: "all" }}
 onClick={() => clicked(r.key)}
 onPointerMove={e => setTip({ x: e.clientX, y: e.clientY, r })}
 onPointerLeave={() => setTip(null)}>
 {!cluster && <circle cx={p.x} cy={p.y} r={12 + t * 30} fill={c} opacity="0.18" />}
 {!cluster && <circle cx={p.x} cy={p.y} r={5 + t * 10} fill={c} fillOpacity="0.92" stroke="#fff" strokeWidth={sel ? 3 : 1.6} />}
 {cluster && <>
 <circle cx={p.x} cy={p.y} r={15 + t * 13} fill={c} stroke="#fff" strokeWidth={sel ? 3 : 2}
 style={{ filter: "drop-shadow(0 1px 3px rgba(18,38,78,.4))" }} />
 <text x={p.x} y={p.y + 4} textAnchor="middle" fontSize="12" fontWeight="800" fill="#fff">{metric(r)}</text>
 </>}
 <text x={p.x} y={p.y - (cluster ? 18 + t * 13 : 15 + t * 30)} textAnchor="middle" fontSize="10" fontWeight="800"
 fill="#10213f" stroke="#fff" strokeWidth="2.5" paintOrder="stroke">{r.name}</text>
 </g>
 );
 })}
 </svg>

 {/* zoom controls */}
 <div style={{ position: "absolute", top: 8, right: 8, display: "flex", flexDirection: "column", gap: 4 }}>
 {([["+", 1], ["–", -1]] as [string, number][]).map(([lbl, dz]) => (
 <button key={lbl} onClick={e => { e.stopPropagation(); zoomTo(dz); }} onPointerDown={e => e.stopPropagation()}
 style={{ width: 28, height: 28, borderRadius: 7, border: "1px solid var(--ci-border-strong)", background: "#fff",
 color: "var(--ci-text)", fontSize: 15, fontWeight: 700, cursor: "pointer", lineHeight: 1, boxShadow: "var(--ci-shadow-soft)" }}>{lbl}</button>
 ))}
 </div>

 {/* attribution */}
 <div style={{ position: "absolute", bottom: 2, right: 4, fontSize: 9, color: "#5b6b88",
 background: "rgba(255,255,255,0.7)", padding: "1px 4px", borderRadius: 4, pointerEvents: "none" }}>© OpenStreetMap</div>

 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{tip.r.name}</b><br />
 <span className="ci-faint">{metric(tip.r).toLocaleString()} {layerWord} · {tip.r.conversion}% conversion</span>
 </div>
 )}
 </div>
 );
}
","import React from "react";
import { VeloPt } from "../../data/command";

const SPORT_COLOR: Record<string, string> = {
 Athletics: "#0a99c7", Swimming: "#12a06d", Taekwondo: "#7c5cff", Cycling: "#d9820a",
 Rowing: "#0bb39a", Judo: "#2f6fed", default: "#8092ad",
};
const initials = (n: string) => n.replace(/[^A-Za-z. ]/g, "").split(/[.\s]+/).filter(Boolean).map(w => w[0]).slice(0, 2).join("").toUpperCase();

// Enlarged quadrant bubble: X = performance, Y = improvement, size = confidence
export function VelocityScatter({ points, onSelect, highlightSport }:
 { points: VeloPt[]; onSelect: (p: VeloPt) => void; highlightSport?: string | null }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; p: VeloPt } | null>(null);
 const w = 640, h = 360, pad = 40;
 const X = (v: number) => pad + (v / 100) * (w - pad * 2);
 const Y = (v: number) => h - pad - (v / 100) * (h - pad * 2);
 const midX = X(50), midY = Y(50);

 const quad = (x: number, y: number, anchor: string, label: string, color: string, strong = false) => (
 <text x={x} y={y} textAnchor={anchor as any} fontSize="10.5" fontWeight="800" fill={color} opacity={strong ? 0.95 : 0.5} letterSpacing="0.04em">{label}</text>
 );

 return (
 <div style={{ position: "relative" }}>
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`} onMouseLeave={() => setTip(null)}>
 {/* emerging / high-growth quadrant (top-left) highlight */}
 <rect x={pad} y={pad} width={midX - pad} height={midY - pad} rx="8" fill="rgba(10,153,199,0.08)" stroke="rgba(10,153,199,0.30)" strokeDasharray="5 4" />
 <line x1={midX} y1={pad} x2={midX} y2={h - pad} stroke="var(--ci-grid-line)" />
 <line x1={pad} y1={midY} x2={w - pad} y2={midY} stroke="var(--ci-grid-line)" />
 <line x1={pad} y1={pad} x2={pad} y2={h - pad} stroke="var(--ci-border)" />
 <line x1={pad} y1={h - pad} x2={w - pad} y2={h - pad} stroke="var(--ci-border)" />

 {quad(pad + 10, pad + 18, "start", "EMERGING · HIGH GROWTH", "#0a99c7", true)}
 {quad(w - pad - 8, pad + 18, "end", "HIGH PERFORMANCE · HIGH GROWTH", "#45577a")}
 {quad(pad + 10, h - pad - 10, "start", "DEVELOPMENT REQUIRED", "#45577a")}
 {quad(w - pad - 8, h - pad - 10, "end", "HIGH PERFORMANCE · LOW GROWTH", "#45577a")}

 <text x={w / 2} y={h - 6} textAnchor="middle">Current performance level →</text>
 <text x={13} y={h / 2} textAnchor="middle" transform={`rotate(-90 13 ${h / 2})`}>Rate of improvement →</text>

 {points.map(p => {
 const emerging = p.perf < 50 && p.growth > 50;
 const c = SPORT_COLOR[p.sport] || SPORT_COLOR.default;
 const muted = highlightSport && p.sport !== highlightSport;
 return (
 <circle key={p.id} cx={X(p.perf)} cy={Y(p.growth)} r={5 + (p.conf / 100) * 11}
 fill={c} fillOpacity={muted ? 0.10 : emerging ? 0.7 : 0.42} stroke={c} strokeWidth={emerging ? 2 : 1.2}
 opacity={muted ? 0.35 : 1}
 style={{ cursor: "pointer", filter: emerging && !muted ? `drop-shadow(0 2px 5px ${c}66)` : "none" }}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, p })}
 onClick={() => onSelect(p)} />
 );
 })}
 </svg>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 14, top: tip.y - 12, minWidth: 190, pointerEvents: "none" }}>
 <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 6 }}>
 <span style={{ width: 30, height: 30, borderRadius: 9, background: SPORT_COLOR[tip.p.sport] || SPORT_COLOR.default,
 color: "#fff", display: "grid", placeItems: "center", fontSize: 11, fontWeight: 800, flex: "none" }}>{initials(tip.p.name)}</span>
 <div style={{ lineHeight: 1.25 }}>
 <b>{tip.p.name}</b><br />
 <span className="ci-faint" style={{ fontSize: 10.5 }}>{tip.p.sport} · {tip.p.region} · age {tip.p.age} · {tip.p.stage}</span>
 </div>
 </div>
 <div style={{ display: "flex", gap: 12, fontSize: 11 }}>
 <span className="ci-faint">Percentile <b style={{ color: "var(--ci-text)" }}>P{tip.p.perf}</b></span>
 <span className="ci-faint">Improvement <b style={{ color: "var(--ci-green)" }}>+{tip.p.growth}%</b></span>
 </div>
 </div>
 )}
 </div>
 );
}
