export function RadarKpiStrip() {
 const { toast } = useRadar();
 return (
 <>
 {RADAR_KPIS.map(k => {
 const color = SC[k.status];
 return (
 <div key={k.id} className="ci-panel ci-panel--hover ci-kpi ci-span-2" role="button" tabIndex={0}
 title={k.support} onClick={() => toast(`Drill-down · ${k.label}`)} onKeyDown={e => e.key === "Enter" && toast(k.label)}>
 <span className="ci-kpi__drill"><Icon.chevron style={{ width: 14, height: 14 }} /></span>
