 );

 return (
 <Panel span={7} hover title="Cohort Explorer"
 sub={`${rows.length} athletes${regionName ? " · " + regionName : ""}${sport ? " · " + sport : ""}${source ? " · " + source : ""}`}
 right={<Button size="sm" variant="primary" icon="plus" onClick={() => { toast(`Cohort created · ${rows.length} athletes`); open("coh", { title: "New Cohort", count: rows.length }); }}>Create Cohort</Button>}>
 <div className="tr-builder">
 {chip("age", "Age 16–21")}
 {chip("top", "Top 10% national")}
 {chip("fast", "Velocity > 75")}
 {chip("notElite", "Not yet elite")}
 </div>
 <div style={{ maxHeight: 260, overflowY: "auto" }}>
 <table className="ci-table tr-table">
