 const ctx = { region, setRegion, sport, setSport, source, setSource, benchId, setBenchId, open, toast };
 const cross = sport || source;

 return (
 <RadarContext.Provider value={ctx}>
 <div className="ci-fade">
 <PageHead title="National Talent Radar"
 desc="Crowdsourced discovery, geographic intelligence and world-class benchmarking across the entire population."
 actions={cross
 ? <Button icon="x" variant="ghost" onClick={() => { setSport(null); setSource(null); toast("Cleared cross-filters"); }}>Clear filters</Button>
 : <Button icon="brain" variant="primary" onClick={() => toast("Ask AI — where should we launch discovery?")}>Ask AI</Button>} />
 <div className="ci-grid">
 <RadarKpiStrip />
 <RadarMapRow />
 <RegionalSnapshot />
 <DiscoveryFunnelRow />
 <SourceMixRow />
 <BenchmarkRow />
 <TalentOppsRow />
 <CohortExplorerRow />
 <ActionQueueRow />
 </div>
 </div>
 <RadarDrawer state={drawer} onClose={() => setDrawer(null)}
 onAction={a => { toast(a + " — action started"); setDrawer(null); }} />
 </RadarContext.Provider>
 );
}
","import React from "react";
import { Chip } from "./KpiCard";
import { Athlete, initials } from "../data/demo";

const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };

export function AthleteTable({ rows, onSelect, columns = ["cpi", "percentile", "readiness", "risk", "momentum"] }:
 { rows: Athlete[]; onSelect: (a: Athlete) => void; columns?: string[] }) {
 const head: Record<string, string> = { cpi: "CPI", percentile: "Percentile", readiness: "Readiness", risk: "Injury Risk", momentum: "Momentum" };
 return (
 <table className="ci-table">
 <thead>
 <tr>
 <th>Athlete</th><th>Stage</th>
 {columns.map(c => <th key={c}>{head[c]}</th>)}
 <th>Status</th>
 </tr>
 </thead>
 <tbody>
 {rows.map((a, i) => (
 <tr key={a.id} onClick={() => onSelect(a)}>
 <td>
 <div className="ci-ident">
 <div className="ci-ident__av" style={{ background: SC[a.status] }}>{initials(a.name)}</div>
 <div className="ci-ident__meta">
 <div className="ci-table__name">{a.name}</div>
 <div className="ci-ident__sub">{a.sport} · {a.region}</div>
 </div>
 </div>
 </td>
 <td><Chip status="ghost">{a.stage}</Chip></td>
 {columns.map(c => {
 if (c === "cpi") return <td key={c}><Meter v={a.potential} color={SC[a.status]} /></td>;
 if (c === "percentile") return <td key={c} className="ci-num">P{a.benchmark}</td>;
 if (c === "readiness") return <td key={c}><Meter v={a.readiness} color="var(--ci-cyan)" /></td>;
 if (c === "risk") return <td key={c} className="ci-num" style={{ color: a.injuryRisk > 62 ? "var(--ci-red)" : a.injuryRisk > 42 ? "var(--ci-amber)" : "var(--ci-text-dim)" }}>{a.injuryRisk}%</td>;
 if (c === "momentum") return <td key={c} className="ci-num" style={{ color: a.momentum >= 0 ? "var(--ci-green)" : "var(--ci-red)" }}>{a.momentum >= 0 ? "+" : ""}{a.momentum}</td>;
 return <td key={c}></td>;
 })}
 <td><span className={`ci-dot ci-dot--${a.status}`} /></td>
 </tr>
 ))}
 </tbody>
 </table>
 );
}

function Meter({ v, color }: { v: number; color: string }) {
 return (
 <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
 <div className="ci-meter"><div className="ci-meter__fill" style={{ width: `${v}%`, background: color }} /></div>
 <span className="ci-num" style={{ fontSize: 11.5 }}>{v}</span>
 </div>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead } from "../common";
import { Button } from "../Button";
import { AthleteTable } from "../AthleteTable";
import { useApp } from "../../context/AppContext";
import { ATHLETES, Athlete } from "../../data/demo";

const SEGMENTS = ["All", "High Potential", "At Risk", "Talent Transfer", "Paralympic"];

export function Athletes({ onAthlete }: { onAthlete: (a: Athlete) => void }) {
 const { navigate } = useApp();
 const [seg, setSeg] = React.useState("All");
 const [q, setQ] = React.useState("");

 const rows = ATHLETES.filter(a => {
 if (q && !a.name.toLowerCase().includes(q.toLowerCase())) return false;
 if (seg === "High Potential") return a.potential > 84;
 if (seg === "At Risk") return a.injuryRisk > 55;
 if (seg === "Talent Transfer") return a.stage === "Talent Transfer" || a.pathway === "Transfer";
 if (seg === "Paralympic") return a.stage === "Paralympic" || a.sport === "Para-Athletics";
 return true;
 });

 return (
 <div className="ci-fade">
 <PageHead title="Athletes" desc="The full tracked population across every stage and pathway. Search, segment and drill into any athlete's 360° profile."
 actions={<Button icon="user" variant="primary" onClick={() => navigate("athlete360")}>Open Athlete 360</Button>} />

 <Panel hover title={`${rows.length} athletes`} sub="Click a row to open the profile drawer"
 right={
 <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
 <div className="ci-search" style={{ minWidth: 200, padding: "6px 12px" }}>
 <input placeholder="Search name…" value={q} onChange={e => setQ(e.target.value)} aria-label="Search athletes" />
 </div>
 <div className="ci-seg">
 {SEGMENTS.map(s => (
 <button key={s} className={`ci-seg__btn ${seg === s ? "ci-seg__btn--active" : ""}`} onClick={() => setSeg(s)}>{s}</button>
 ))}
 </div>
 </div>
 }>
 <AthleteTable rows={rows} onSelect={onAthlete} />
 </Panel>
 </div>
 );
}
